// ============================================================
// SkyMind - Ground Operations Data Preparation
// ============================================================

const flightData =
  $('Prepare Flight Data').first().json || {};

const recoveryRaw =
  $('Recovery Agent').first().json || {};

const weatherData =
  $('Weather request').first().json || {};


// ------------------------------------------------------------
// Recovery Agent output
// ------------------------------------------------------------

const recovery =
  recoveryRaw.output ||
  recoveryRaw;


// ------------------------------------------------------------
// DELAY
// ------------------------------------------------------------

const calculatedDelay =
  Number(
    flightData.calculated_delay_minutes
  );

const recoveryDelay =
  Number(
    recovery.delay_minutes
  );

let delayMinutes = 0;

if (!Number.isNaN(calculatedDelay)) {
  delayMinutes = calculatedDelay;
}
else if (!Number.isNaN(recoveryDelay)) {
  delayMinutes = recoveryDelay;
}


// ------------------------------------------------------------
// Delay severity
// ------------------------------------------------------------

let delaySeverity = 'ON TIME';

if (delayMinutes >= 120) {
  delaySeverity = 'MAJOR';
}
else if (delayMinutes >= 60) {
  delaySeverity = 'SIGNIFICANT';
}
else if (delayMinutes > 0) {
  delaySeverity = 'MINOR';
}


// ------------------------------------------------------------
// Operational priority
// ------------------------------------------------------------

let operationalPriority = 'LOW';

if (delayMinutes >= 120) {
  operationalPriority = 'HIGH';
}
else if (delayMinutes >= 60) {
  operationalPriority = 'MEDIUM';
}


// ------------------------------------------------------------
// Weather
// ------------------------------------------------------------

const current =
  weatherData.current || {};

const location =
  weatherData.location || {};


// ------------------------------------------------------------
// Recovery
// ------------------------------------------------------------

const recoveryRequired =
  recovery.recovery_required === true;

const recoveryActions =
  Array.isArray(
    recovery.recovery_actions
  )
    ? recovery.recovery_actions
    : [];

const passengerCommunicationRequired =
  recovery.passenger_communication_required === true;

const passengerMessage =
  recovery.passenger_message ||
  'Not available';

const operationsMessage =
  recovery.operations_message ||
  'Not available';


// ------------------------------------------------------------
// Ground operations data
// ------------------------------------------------------------

return [
  {
    json: {

      flight: {

        flight_number:
          flightData.flight_number ||
          recovery.flight_number ||
          'Not available',

        flight_status:
          flightData.flight_status ||
          recovery.flight_status ||
          'Not available',

        flight_date:
          flightData.flight_date ||
          recovery.flight_date ||
          'Not available',

        departure_airport:
          flightData.departure?.iata ||
          recovery.departure_airport ||
          'Not available',

        arrival_airport:
          flightData.arrival?.iata ||
          recovery.arrival_airport ||
          'Not available',

        scheduled_departure:
          flightData.departure?.scheduled ||
          recovery.scheduled_departure ||
          'Not available',

        estimated_departure:
          flightData.departure?.estimated ||
          'Not available',

        actual_departure:
          flightData.departure?.actual ||
          recovery.actual_departure ||
          'Not available',

        scheduled_arrival:
          flightData.arrival?.scheduled ||
          'Not available',

        estimated_arrival:
          flightData.arrival?.estimated ||
          'Not available',

        actual_arrival:
          flightData.arrival?.actual ||
          'Not available'
      },


      delay: {

        delay_minutes:
          delayMinutes,

        severity:
          delaySeverity,

        operational_priority:
          operationalPriority
      },


      weather: {

        airport:
          flightData.arrival?.iata ||
          'Not available',

        location:
          location.name ||
          'Not available',

        condition:
          current.condition?.text ||
          'Not available',

        temperature_c:
          current.temp_c ??
          null,

        wind_kph:
          current.wind_kph ??
          null,

        wind_direction:
          current.wind_dir ||
          'Not available',

        visibility_km:
          current.vis_km ??
          null,

        last_updated:
          current.last_updated ||
          'Not available'
      },


      recovery: {

        required:
          recoveryRequired,

        actions:
          recoveryActions,

        passenger_communication_required:
          passengerCommunicationRequired,

        passenger_message:
          passengerMessage,

        operations_message:
          operationsMessage
      }
    }
  }
];

// ============================================================
// SkyMind - Final Ground Staff Response
// ============================================================

const groundData =
  $('Code in JavaScript').first().json || {};

const llmData =
  $input.first().json || {};


// ------------------------------------------------------------
// Delay
// ------------------------------------------------------------

const delayMinutes =
  Math.max(
    0,
    Number(
      groundData.delay?.delay_minutes
    ) || 0
  );


// ------------------------------------------------------------
// Severity
// ------------------------------------------------------------

let severity = 'ON TIME';

if (delayMinutes >= 120) {
  severity = 'MAJOR';
}
else if (delayMinutes >= 60) {
  severity = 'SIGNIFICANT';
}
else if (delayMinutes > 0) {
  severity = 'MINOR';
}


// ------------------------------------------------------------
// Priority
// ------------------------------------------------------------

let priority = 'LOW';

if (delayMinutes >= 120) {
  priority = 'HIGH';
}
else if (delayMinutes >= 60) {
  priority = 'MEDIUM';
}


// ------------------------------------------------------------
// Final response
// ------------------------------------------------------------

return [
  {
    json: {

      success: true,

      audience: 'GROUND_STAFF',

      flight_number:
        groundData.flight?.flight_number ||
        'Not available',

      flight_status:
        groundData.flight?.flight_status ||
        'Not available',

      flight_date:
        groundData.flight?.flight_date ||
        'Not available',

      departure_airport:
        groundData.flight?.departure_airport ||
        'Not available',

      arrival_airport:
        groundData.flight?.arrival_airport ||
        'Not available',

      scheduled_departure:
        groundData.flight?.scheduled_departure ||
        'Not available',

      estimated_departure:
        groundData.flight?.estimated_departure ||
        'Not available',

      actual_departure:
        groundData.flight?.actual_departure ||
        'Not available',

      scheduled_arrival:
        groundData.flight?.scheduled_arrival ||
        'Not available',

      estimated_arrival:
        groundData.flight?.estimated_arrival ||
        'Not available',

      actual_arrival:
        groundData.flight?.actual_arrival ||
        'Not available',

      delay_minutes:
        delayMinutes,

      delay_severity:
        severity,

      operational_priority:
        priority,

      weather:
        groundData.weather || {},

      recovery:
        groundData.recovery || {},

      ground_staff_report:
        llmData.text ||
        llmData.output ||
        'Ground operations report generated successfully.'
    }
  }
];

// ============================================================
// SkyMind - Flight Request Preparation
// ============================================================

const body = $('Webhook').first().json.body || {};

const flightNumber = String(
  body.flight_number || ''
)
  .trim()
  .toUpperCase()
  .replace(/\s+/g, '');

if (!flightNumber) {
  throw new Error('Flight number is required.');
}

return [
  {
    json: {
      success: true,

      requested_flight: flightNumber,

      original_request: body,

      aviationstack_query: {
        flight_iata: flightNumber
      }
    }
  }
];

// ============================================================
// SkyMind - Prepare Flight Data
// ============================================================

const apiResponse = $input.first().json;

const requestedFlight =
  $('Code in JavaScript2').first().json.requested_flight;

// ------------------------------------------------------------
// Aviationstack response
// ------------------------------------------------------------

const flight =
  apiResponse?.data?.[0];

if (!flight) {
  throw new Error(
    `No flight data returned for ${requestedFlight}.`
  );
}

// ------------------------------------------------------------
// Helper
// ------------------------------------------------------------

function clean(value) {
  return (
    value !== null &&
    value !== undefined &&
    value !== ''
  )
    ? value
    : null;
}

// ------------------------------------------------------------
// Flight
// ------------------------------------------------------------

const flightNumber =
  flight.flight?.iata ||
  requestedFlight;

const flightStatus =
  flight.flight_status ||
  'unknown';

const flightDate =
  flight.flight_date ||
  null;

// ------------------------------------------------------------
// Departure
// ------------------------------------------------------------

const scheduledDeparture =
  clean(
    flight.departure?.scheduled
  );

const estimatedDeparture =
  clean(
    flight.departure?.estimated
  );

const actualDeparture =
  clean(
    flight.departure?.actual
  );

const departureDelay =
  flight.departure?.delay !== null &&
  flight.departure?.delay !== undefined
    ? Number(flight.departure.delay)
    : null;

// ------------------------------------------------------------
// Arrival
// ------------------------------------------------------------

const scheduledArrival =
  clean(
    flight.arrival?.scheduled
  );

const estimatedArrival =
  clean(
    flight.arrival?.estimated
  );

const actualArrival =
  clean(
    flight.arrival?.actual
  );

const arrivalDelay =
  flight.arrival?.delay !== null &&
  flight.arrival?.delay !== undefined
    ? Number(flight.arrival.delay)
    : null;

// ------------------------------------------------------------
// Delay calculation
//
// Priority:
// 1. Actual - Scheduled
// 2. Estimated - Scheduled
// 3. Aviationstack delay
// ------------------------------------------------------------

function getTimestamp(value) {

  if (!value) {
    return NaN;
  }

  const timestamp =
    new Date(value).getTime();

  return timestamp;
}

function calculateDelay(
  scheduled,
  estimated,
  actual,
  apiDelay
) {

  const scheduledTime =
    getTimestamp(scheduled);

  const estimatedTime =
    getTimestamp(estimated);

  const actualTime =
    getTimestamp(actual);

  // ----------------------------------------------------------
  // ACTUAL departure
  // ----------------------------------------------------------

  if (
    !Number.isNaN(scheduledTime) &&
    !Number.isNaN(actualTime)
  ) {

    return Math.max(
      0,
      Math.round(
        (actualTime - scheduledTime) / 60000
      )
    );
  }

  // ----------------------------------------------------------
  // ESTIMATED departure
  // ----------------------------------------------------------

  if (
    !Number.isNaN(scheduledTime) &&
    !Number.isNaN(estimatedTime)
  ) {

    return Math.max(
      0,
      Math.round(
        (estimatedTime - scheduledTime) / 60000
      )
    );
  }

  // ----------------------------------------------------------
  // Aviationstack delay
  // ----------------------------------------------------------

  if (
    apiDelay !== null &&
    !Number.isNaN(Number(apiDelay))
  ) {

    return Math.max(
      0,
      Math.round(Number(apiDelay))
    );
  }

  return 0;
}

const calculatedDelay =
  calculateDelay(
    scheduledDeparture,
    estimatedDeparture,
    actualDeparture,
    departureDelay
  );

// ------------------------------------------------------------
// Delay severity
// ------------------------------------------------------------

let delaySeverity = 'ON TIME';

if (calculatedDelay >= 120) {
  delaySeverity = 'MAJOR';
}
else if (calculatedDelay >= 60) {
  delaySeverity = 'SIGNIFICANT';
}
else if (calculatedDelay > 0) {
  delaySeverity = 'MINOR';
}

// ------------------------------------------------------------
// Aircraft
// ------------------------------------------------------------

const aircraft = {
  registration:
    flight.aircraft?.registration || null,

  iata:
    flight.aircraft?.iata || null,

  icao:
    flight.aircraft?.icao || null
};

// ------------------------------------------------------------
// Final output
// ------------------------------------------------------------

return [
  {
    json: {

      success: true,

      flight_number:
        flightNumber,

      flight_status:
        flightStatus,

      flight_date:
        flightDate,

      airline: {
        name:
          flight.airline?.name || null,

        iata:
          flight.airline?.iata || null,

        icao:
          flight.airline?.icao || null
      },

      aircraft,

      departure: {

        airport:
          flight.departure?.airport || null,

        iata:
          flight.departure?.iata || null,

        terminal:
          flight.departure?.terminal || null,

        gate:
          flight.departure?.gate || null,

        scheduled:
          scheduledDeparture,

        estimated:
          estimatedDeparture,

        actual:
          actualDeparture,

        delayMinutes:
          departureDelay
      },

      arrival: {

        airport:
          flight.arrival?.airport || null,

        iata:
          flight.arrival?.iata || null,

        terminal:
          flight.arrival?.terminal || null,

        gate:
          flight.arrival?.gate || null,

        scheduled:
          scheduledArrival,

        estimated:
          estimatedArrival,

        actual:
          actualArrival,

        delayMinutes:
          arrivalDelay
      },

      calculated_delay_minutes:
        calculatedDelay,

      delay_severity:
        delaySeverity,

      recommended_action:
        calculatedDelay >= 120
          ? 'Major delay - recovery assessment required'
          : calculatedDelay >= 60
            ? 'Significant delay - monitor and assess recovery'
            : calculatedDelay > 0
              ? 'Minor delay - continue monitoring'
              : 'Normal operations',

      debug: {

        scheduled_departure:
          scheduledDeparture,

        estimated_departure:
          estimatedDeparture,

        actual_departure:
          actualDeparture,

        aviationstack_delay:
          departureDelay,

        calculated_delay_minutes:
          calculatedDelay
      }
    }
  }
];
